local MortarPestleMaker = {}
local PRODUCTS = {
    iron_mortar = { name = "Železni možnar", ironCost = 2, woodCost = 1, leatherCost = 1, time = 5, cost = 145, prestige = 3, happiness = 1, description = "Železni možnar za drobljenje zelišč." },
    bronze_mortar = { name = "Bronast možnar", bronzeCost = 2, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 350, prestige = 5, happiness = 2, description = "Bronast možnar za apoteko." },
    silver_mortar = { name = "Srebrni možnar", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 840, prestige = 10, happiness = 3, description = "Srebrni možnar za plemiške lekarne." },
    gilded_mortar = { name = "Pozlačeni možnar", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 1800, prestige = 19, happiness = 4, description = "Pozlačeni možnar za dvorno lekarno." },
    jewel_set_mortar = { name = "Draguljasti možnar", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 3900, prestige = 35, happiness = 6, description = "Draguljasti možnar za kraljevo lekarno." },
    royal_sovereign_mortar = { name = "Kraljevski suvereni možnar", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 8300, prestige = 67, happiness = 12, description = "Suvereni možnar z biseri za krono." },
}
local BUILDINGS = {
    mortar_workshop = { name = "Možnarska delavnica", cost = { gold = 330, wood = 170, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    mortar_house = { name = "Možnarska hiša", cost = { gold = 1200, wood = 350, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_mortar_atelier = { name = "Mojstrski možnarski atelje", cost = { gold = 3000, wood = 410, stone = 515, silver = 35, gold = 7 }, upkeep = 71, qualityBonus = 30 },
    sovereign_apothecary_palace = { name = "Suverena lekarniška palača", cost = { gold = 12900, wood = 620, stone = 825, gold = 82, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MortarPestleMaker.ironStock = 12; MortarPestleMaker.bronzeStock = 10; MortarPestleMaker.woodStock = 14; MortarPestleMaker.leatherStock = 10; MortarPestleMaker.silverStock = 8; MortarPestleMaker.goldStock = 6; MortarPestleMaker.jewelStock = 4; MortarPestleMaker.pearlStock = 4
MortarPestleMaker.productStock = {}; MortarPestleMaker.buildings = {}; MortarPestleMaker.maker = nil; MortarPestleMaker.activeMaking = {}; MortarPestleMaker.totalProducts = 0; MortarPestleMaker.dayTimer = 0
function MortarPestleMaker.init() MortarPestleMaker.ironStock=12; MortarPestleMaker.bronzeStock=10; MortarPestleMaker.woodStock=14; MortarPestleMaker.leatherStock=10; MortarPestleMaker.silverStock=8; MortarPestleMaker.goldStock=6; MortarPestleMaker.jewelStock=4; MortarPestleMaker.pearlStock=4; MortarPestleMaker.productStock={}; MortarPestleMaker.buildings={}; MortarPestleMaker.maker=nil; MortarPestleMaker.activeMaking={}; MortarPestleMaker.totalProducts=0; MortarPestleMaker.dayTimer=0; print("[MortarPestleMaker] Royal Mortar and Pestle Maker System initialized (6 products, 4 buildings)") end
function MortarPestleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MortarPestleMaker.maker={name=n or ("Možnarar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Možnarar najet: %s (spretnost: %d)",MortarPestleMaker.maker.name,s),"success") end; return true end
function MortarPestleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MortarPestleMaker.build(id) local ok,e=MortarPestleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MortarPestleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MortarPestleMaker.getQualityBonus() local b=0; for _,bd in ipairs(MortarPestleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MortarPestleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MortarPestleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MortarPestleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MortarPestleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MortarPestleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MortarPestleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MortarPestleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MortarPestleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MortarPestleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MortarPestleMaker.buildings==0 then return false,"Potrebna možnarska delavnica" end; if not MortarPestleMaker.maker then return false,"Potreben možnarar" end; return true end
function MortarPestleMaker.make(pt,qty) qty=qty or 1; local ok,e=MortarPestleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MortarPestleMaker.ironStock=MortarPestleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MortarPestleMaker.bronzeStock=MortarPestleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MortarPestleMaker.woodStock=MortarPestleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MortarPestleMaker.leatherStock=MortarPestleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MortarPestleMaker.silverStock=MortarPestleMaker.silverStock-d.silverCost*qty end; if d.goldCost then MortarPestleMaker.goldStock=MortarPestleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MortarPestleMaker.jewelStock=MortarPestleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MortarPestleMaker.pearlStock=MortarPestleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MortarPestleMaker.maker then t=math.max(1,t-math.floor(MortarPestleMaker.maker.skill/13)) end; table.insert(MortarPestleMaker.activeMaking,{id="mortar_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MortarPestleMaker.completeMaking(m) local q=1.0+(MortarPestleMaker.getQualityBonus()/100); if MortarPestleMaker.maker then q=q+(MortarPestleMaker.maker.skill/140) end; q=math.min(2.5,q); MortarPestleMaker.productStock[m.productType]=(MortarPestleMaker.productStock[m.productType] or 0)+m.quantity; MortarPestleMaker.totalProducts=MortarPestleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MortarPestleMaker.maker then MortarPestleMaker.maker.itemsMade=MortarPestleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MortarPestleMaker.maker.skill=math.min(100,MortarPestleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Možnar izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mortar.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MortarPestleMaker.update(dt) if not _G.state then return end; MortarPestleMaker.dayTimer=MortarPestleMaker.dayTimer+dt; if MortarPestleMaker.dayTimer>=30 then MortarPestleMaker.dayTimer=0; for i=#MortarPestleMaker.activeMaking,1,-1 do local m=MortarPestleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MortarPestleMaker.completeMaking(m); table.remove(MortarPestleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MortarPestleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MortarPestleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MortarPestleMaker.getStats() return {ironStock=MortarPestleMaker.ironStock,bronzeStock=MortarPestleMaker.bronzeStock,woodStock=MortarPestleMaker.woodStock,leatherStock=MortarPestleMaker.leatherStock,silverStock=MortarPestleMaker.silverStock,goldStock=MortarPestleMaker.goldStock,jewelStock=MortarPestleMaker.jewelStock,pearlStock=MortarPestleMaker.pearlStock,productStock=MortarPestleMaker.productStock,numBuildings=#MortarPestleMaker.buildings,hasMaker=MortarPestleMaker.maker~=nil,makerName=MortarPestleMaker.maker and MortarPestleMaker.maker.name or "—",makerSkill=MortarPestleMaker.maker and MortarPestleMaker.maker.skill or 0,activeMaking=#MortarPestleMaker.activeMaking,totalProducts=MortarPestleMaker.totalProducts} end
return MortarPestleMaker
